await configureWorkflow({
  name: "API Server",
  command: "cd artifacts/api-server && pnpm run build && PORT=8080 node --enable-source-maps ./dist/index.mjs",
  waitForPort: 8080,
  outputType: "console",
  autoStart: true,
});
console.log("API Server workflow configured");

// Configure frontend workflow (webview, port 5000)
await configureWorkflow({
  name: "Start application",
  command: "cd artifacts/kurdish-pos && PORT=5000 pnpm run dev",
  waitForPort: 5000,
  outputType: "webview",
  autoStart: true,
});
console.log("Frontend workflow configured");

const api = await getWorkflowStatus({ name: "API Server", maxScrollbackLines: 20 });
const frontend = await getWorkflowStatus({ name: "Start application", maxScrollbackLines: 20 });
console.log("API Server state:", api.state, "\nOutput:", api.output);
console.log("Frontend state:", frontend.state, "\nOutput:", frontend.output);

// Remove the duplicate manual API Server workflow
await removeWorkflow({ name: "API Server" });
console.log("Removed duplicate API Server workflow");

const api = await getWorkflowStatus({ name: "artifacts/api-server: API Server", maxScrollbackLines: 15 });
console.log("API Server state:", api.state);
console.log("Output:", api.output);

