   121→function AnimatedBackground() {
   122→  const canvasRef = useRef<HTMLCanvasElement>(null);
   123→  useEffect(() => {
   124→    const canvas = canvasRef.current; if (!canvas) return;
   125→    const ctx = canvas.getContext("2d"); if (!ctx) return;
   126→    let raf: number;
   127→    const resize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
   128→    resize(); window.addEventListener("resize", resize);
   129→    const TYPES: IconType[] = ["truck","cart","box","store"];
   130→    const icons = Array.from({ length: 20 }, (_, i) => ({
   131→      x: Math.random()*window.innerWidth, y: Math.random()*window.innerHeight,
   132→      vx: (Math.random()-.5)*.3, vy: (Math.random()-.5)*.3,
   133→      size: 16+Math.random()*14, type: TYPES[i%4],
   134→      pulse: Math.random()*Math.PI*2, pulseSpeed: .015+Math.random()*.02,
   135→      baseAlpha: .4+Math.random()*.28,
   136→    }));
   137→    const orbs = [
   138→      { x:window.innerWidth*.18, y:window.innerHeight*.28, vx:.14, vy:.09, r:300 },
   139→      { x:window.innerWidth*.82, y:window.innerHeight*.72, vx:-.11, vy:-.08, r:240 },
   140→      { x:window.innerWidth*.55, y:window.innerHeight*.05, vx:.07, vy:.16, r:200 },
   141→      { x:window.innerWidth*.1,  y:window.innerHeight*.88, vx:.1,  vy:-.07, r:170 },
   142→    ];
   143→    let tick = 0;
   144→    const draw = () => {
   145→      const W = canvas.width, H = canvas.height;
   146→      ctx.fillStyle = "#020C1C"; ctx.fillRect(0,0,W,H);
   147→      const z1 = ctx.createRadialGradient(W*.22,H*.5,0,W*.22,H*.5,W*.48);
   148→      z1.addColorStop(0,"rgba(29,78,216,.38)"); z1.addColorStop(.4,"rgba(37,99,235,.18)"); z1.addColorStop(1,"rgba(10,30,80,0)");
   149→      ctx.fillStyle=z1; ctx.fillRect(0,0,W,H);
   150→      const z2 = ctx.createRadialGradient(W*.92,H*.08,0,W*.92,H*.08,W*.38);
   151→      z2.addColorStop(0,"rgba(6,182,212,.22)"); z2.addColorStop(.5,"rgba(14,116,144,.10)"); z2.addColorStop(1,"rgba(0,0,0,0)");
   152→      ctx.fillStyle=z2; ctx.fillRect(0,0,W,H);
   153→      const p3 = .12+.05*Math.sin(tick*.012);
   154→      const z3 = ctx.createRadialGradient(W*.05,H*.92,0,W*.05,H*.92,W*.35);
   155→      z3.addColorStop(0,`rgba(79,70,229,${p3})`); z3.addColorStop(1,"rgba(0,0,0,0)");
   156→      ctx.fillStyle=z3; ctx.fillRect(0,0,W,H);
   157→      const p4 = .09+.04*Math.sin(tick*.009+1.2);
   158→      const z4 = ctx.createRadialGradient(W*.5,H*.5,0,W*.5,H*.5,W*.55);
   159→      z4.addColorStop(0,`rgba(59,130,246,${p4})`); z4.addColorStop(.6,`rgba(37,99,235,${p4*.3})`); z4.addColorStop(1,"rgba(0,0,0,0)");
   160→      ctx.fillStyle=z4; ctx.fillRect(0,0,W,H);
   161→      for(const orb of orbs){
   162→        orb.x+=orb.vx; orb.y+=orb.vy;
   163→        if(orb.x<-orb.r||orb.x>W+orb.r) orb.vx*=-1;
   164→        if(orb.y<-orb.r||orb.y>H+orb.r) orb.vy*=-1;
   165→        const g=ctx.createRadialGradient(orb.x,orb.y,0,orb.x,orb.y,orb.r);
   166→        g.addColorStop(0,"rgba(99,179,255,.22)"); g.addColorStop(.45,"rgba(59,130,246,.10)"); g.addColorStop(1,"rgba(29,78,216,0)");
   167→        ctx.fillStyle=g; ctx.beginPath(); ctx.arc(orb.x,orb.y,orb.r,0,Math.PI*2); ctx.fill();
   168→      }
   169→      ctx.textAlign="center"; ctx.textBaseline="middle";
   170→      [{x:.18,y:.22,s:80,ph:0},{x:.78,y:.72,s:56,ph:1.8},{x:.5,y:.92,s:44,ph:3.4}].forEach(wm=>{
   171→        const a=.18+.06*Math.sin(tick*.007+wm.ph);
   172→        ctx.font=`bold ${wm.s}px system-ui`; ctx.fillStyle=`rgba(147,197,253,${a})`;
   173→        ctx.fillText("LinQi",W*wm.x,H*wm.y);
   174→      });
   175→      for(const ic of icons){
   176→        ic.x+=ic.vx; ic.y+=ic.vy; ic.pulse+=ic.pulseSpeed;
   177→        if(ic.x<-ic.size) ic.x=W+ic.size; if(ic.x>W+ic.size) ic.x=-ic.size;
   178→        if(ic.y<-ic.size) ic.y=H+ic.size; if(ic.y>H+ic.size) ic.y=-ic.size;
   179→      }
   180→      const MAX=160;
   181→      for(let i=0;i<icons.length;i++) for(let j=i+1;j<icons.length;j++){
   182→        const dx=icons[i].x-icons[j].x,dy=icons[i].y-icons[j].y,d2=dx*dx+dy*dy;
   183→        if(d2<MAX*MAX){const d=Math.sqrt(d2);
   184→          ctx.strokeStyle=`rgba(96,165,250,${(1-d/MAX)*.45})`; ctx.lineWidth=.9;
   185→          ctx.beginPath(); ctx.moveTo(icons[i].x,icons[i].y); ctx.lineTo(icons[j].x,icons[j].y); ctx.stroke();}
   186→      }
   187→      for(const ic of icons) drawIcon(ctx,ic.type,ic.x,ic.y,ic.size,ic.baseAlpha+.08*Math.sin(ic.pulse));
   188→      tick++; raf=requestAnimationFrame(draw);
   189→    };
   190→    draw();
   191→    return ()=>{ cancelAnimationFrame(raf); window.removeEventListener("resize",resize); };
   192→  },[]);
   193→  return <canvas ref={canvasRef} className="fixed inset-0 w-full h-full" style={{zIndex:0}} />;
   194→}
