   196→/* ─── Progress Tracker ───────────────────────────────────────────────────── */
   197→function ProgressBar({ step, total }: { step: number; total: number }) {
   198→  const { t } = useTranslation();
   199→  const labels = [t("onboard.step1Label"), t("onboard.step2Label"), t("onboard.step3Label"), t("onboard.step4Label")];
   200→  return (
   201→    <div className="px-6 pt-5 pb-4">
   202→      <div className="flex items-start justify-between relative">
   203→        <div className="absolute top-4 start-8 end-8 h-px z-0" style={{ background: "rgba(255,255,255,0.12)" }}>
   204→          <motion.div className="h-full rounded-full" style={{ background: "linear-gradient(90deg,#3B82F6,#60A5FA)", width: `${((step-1)/(total-1))*100}%` }} transition={{ duration: 0.4 }} />
   205→        </div>
   206→        {Array.from({ length: total }, (_,i) => {
   207→          const n=i+1, done=n<step, active=n===step;
   208→          return (
   209→            <div key={n} className="flex flex-col items-center z-10 flex-1">
   210→              <motion.div layout className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold border-2 transition-all duration-300 ${
   211→                done  ? "border-blue-400 bg-blue-500 text-white" :
   212→                active? "border-blue-400 text-blue-300" :
   213→                        "text-white/30"
   214→              }`} style={active ? { background:"rgba(59,130,246,0.2)" } : done ? {} : { background:"rgba(255,255,255,0.05)", borderColor:"rgba(255,255,255,0.12)" }}>
   215→                {done ? <Check className="w-4 h-4" /> : <span>{n}</span>}
   216→              </motion.div>
   217→              <p className={`text-[10px] mt-1.5 text-center font-medium leading-tight max-w-[64px] ${active?"text-blue-300":done?"text-blue-400/70":"text-white/30"}`}>
   218→                {labels[i]}
   219→              </p>
   220→            </div>
   221→          );
   222→        })}
   223→      </div>
   224→    </div>
   225→  );
   226→}
   227→
   228→/* ─── Shared Input ───────────────────────────────────────────────────────── */
   229→function glassInputClass(error?: string) {
   230→  return `w-full py-2.5 rounded-xl outline-none transition-all text-sm text-white placeholder-[#94A3B8] ${error ? "ring-2 ring-red-500/60" : ""}`;
   231→}
   232→
   233→function Input({ label, error, icon: Icon, type = "text", ...props }: any) {
   234→  const [show, setShow] = useState(false);
   235→  const isPass = type === "password";
   236→  return (
   237→    <div>
   238→      {label && (
   239→        <label className="block text-xs font-semibold mb-1.5 uppercase tracking-wide" style={{ color: "#E2E8F0", letterSpacing: "0.06em" }}>
   240→          {label}
   241→        </label>
   242→      )}
   243→      <div className="relative">
   244→        {Icon && <Icon className="absolute start-3 top-1/2 -translate-y-1/2 w-4 h-4 pointer-events-none" style={{ color: "#94A3B8" }} />}
   245→        <input
   246→          type={isPass ? (show ? "text" : "password") : type}
   247→          {...props}
   248→          className={`${glassInputClass(error)} ${Icon ? "ps-9" : "ps-3.5"} ${isPass ? "pe-10" : "pe-3.5"}`}
   249→          style={{ ...glass.input, borderRadius: "0.75rem" }}
   250→          onFocus={e => { e.currentTarget.style.border = glass.inputFocusBorder; e.currentTarget.style.boxShadow = glass.inputFocusShadow; }}
   251→          onBlur={e  => { e.currentTarget.style.border = "1px solid rgba(255,255,255,0.12)"; e.currentTarget.style.boxShadow = "none"; }}
   252→        />
   253→        {isPass && (
   254→          <button type="button" onClick={()=>setShow(v=>!v)} className="absolute end-3 top-1/2 -translate-y-1/2" style={{ color: "#94A3B8" }}>
   255→            {show ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
   256→          </button>
   257→        )}
   258→      </div>
   259→      {error && <p className="text-[11px] text-red-400 mt-1">{error}</p>}
   260→    </div>
   261→  );
   262→}
   263→
   264→function GSelect({ label, error, children, ...props }: any) {
