/* ─── GPS Address Field ────────────────────────────────────────────── */
function GpsAddressField({ label, value, onChange }: { label: string; value: string; onChange: (v: string) => void }) {
  const { t } = useTranslation();
  const [loading, setLoading] = useState(false);
  const [ok, setOk] = useState(false);
  const [err, setErr] = useState("");

  const fetchGPS = () => {
    if (!navigator.geolocation) { setErr(t("onboard.gpsUnsupported")); return; }
    setLoading(true); setErr(""); setOk(false);
    navigator.geolocation.getCurrentPosition(
      async pos => {
        const { latitude: lat, longitude: lng } = pos.coords;
        try {
          const res = await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json`);
          const data = await res.json();
          onChange(data.display_name ?? `${lat.toFixed(5)}, ${lng.toFixed(5)}`);
          setOk(true); setTimeout(()=>setOk(false), 3500);
        } catch { onChange(`${lat.toFixed(5)}, ${lng.toFixed(5)}`); setOk(true); }
        finally { setLoading(false); }
      },
      () => { setErr(t("onboard.gpsDenied")); setLoading(false); },
      { timeout: 10000, enableHighAccuracy: true }
    );
  };

  return (
    <div>
      <label className="block text-xs font-semibold mb-1.5 uppercase tracking-wide" style={{ color:"#E2E8F0", letterSpacing:"0.06em" }}>{label}</label>
      <div className="relative">
        <motion.button type="button" onClick={fetchGPS} disabled={loading}
          whileHover={!loading?{scale:1.12}:{}} whileTap={!loading?{scale:0.88}:{}}
          className="absolute start-0 top-0 bottom-0 px-3 flex items-center justify-center rounded-s-xl z-10"
          style={{ color: loading?"#60A5FA":ok?"#34D399":"#94A3B8", background:"transparent", cursor:loading?"default":"pointer" }}>
          <AnimatePresence mode="wait">
            {loading ? (
              <motion.div key="spin" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}
                className="w-4 h-4 border-2 rounded-full animate-spin" style={{ borderColor:"rgba(99,179,255,0.3)", borderTopColor:"#60A5FA" }} />
            ) : ok ? (
              <motion.div key="ok" initial={{scale:0.5,opacity:0}} animate={{scale:1,opacity:1}} exit={{opacity:0}} transition={{type:"spring",stiffness:320,damping:18}}>
                <Check className="w-4 h-4" style={{ color:"#34D399" }} />
              </motion.div>
            ) : (
              <motion.div key="pin" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}>
                <MapPin className="w-4 h-4" />
              </motion.div>
            )}
          </AnimatePresence>
        </motion.button>
        <input type="text" value={value} onChange={e=>onChange(e.target.value)}
          placeholder={loading ? t("onboard.gpsFetching") : t("onboard.addressPh")}
          className="w-full ps-9 pe-3.5 py-2.5 rounded-xl text-sm text-white placeholder-[#94A3B8] outline-none transition-all"
          style={{ ...glass.input, borderRadius:"0.75rem", ...(ok?{border:"1px solid rgba(52,211,153,0.5)",boxShadow:"0 0 0 3px rgba(52,211,153,0.12)"}:{}) }}
          onFocus={e=>{e.currentTarget.style.border=glass.inputFocusBorder;e.currentTarget.style.boxShadow=glass.inputFocusShadow;}}
          onBlur={e=>{ if(ok){e.currentTarget.style.border="1px solid rgba(52,211,153,0.5)";e.currentTarget.style.boxShadow="0 0 0 3px rgba(52,211,153,0.12)";}
            else{e.currentTarget.style.border="1px solid rgba(255,255,255,0.12)";e.currentTarget.style.boxShadow="none";} }}
        />
        <AnimatePresence>
          {loading && (
            <motion.div initial={{scaleX:0}} animate={{scaleX:1}} exit={{opacity:0}}
              className="absolute bottom-0 start-0 end-0 h-0.5 rounded-full origin-start"
              style={{ background:"linear-gradient(90deg,#3B82F6,#06B6D4,#3B82F6)" }}
              transition={{ duration:1.4, repeat:Infinity, repeatType:"reverse" }} />
          )}
        </AnimatePresence>
      </div>
      {err && <p className="text-[11px] text-red-400 mt-1">{err}</p>}
    </div>
  );
}

