/* PENDING REVIEW LOCK SCREEN                                          */
/* ═══════════════════════════════════════════════════════════════════ */
function PendingReviewScreen({ sectorKey, businessName }: { sectorKey: string; businessName: string }) {
  const { t } = useTranslation();
  const sector = SECTORS.find(s=>s.key===sectorKey);
  const SectorIcon = sector?.icon ?? Package;
  const color = sector?.color ?? "#3B82F6";

  const steps = [
    { ku: "داواکاری وەرگیرا", en: "Application received",    done: true },
    { ku: "پشکنینی بەڵگەنامەکان", en: "Documents under review", done: false },
    { ku: "دڵنیاکردنەوەی GPS", en: "GPS verification",        done: false },
    { ku: "چالاکردنی ئەکاونت", en: "Account activation",       done: false },
  ];

  return (
    <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} className="px-6 pb-8 flex flex-col items-center">
      {/* Lock icon */}
      <motion.div
        initial={{ scale:0, rotate:-30 }} animate={{ scale:1, rotate:0 }}
        transition={{ type:"spring", stiffness:180, damping:14 }}
        className="w-24 h-24 rounded-full flex items-center justify-center mb-5 mt-2 relative"
        style={{ background:"rgba(245,158,11,0.15)", border:"2px solid rgba(245,158,11,0.5)", boxShadow:"0 0 48px rgba(245,158,11,0.25)" }}>
        <motion.div
          animate={{ y: [0, -3, 0] }}
          transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}>
          <Lock className="w-12 h-12" style={{ color:"#FBBF24" }} />
        </motion.div>
        {/* Pulse rings */}
        {[0,1].map(i=>(
          <motion.div key={i} className="absolute inset-0 rounded-full"
            animate={{ scale:[1,1.5+i*.3], opacity:[0.5,0] }}
            transition={{ duration:2, repeat:Infinity, delay:i*.7, ease:"easeOut" }}
            style={{ border:"1.5px solid rgba(245,158,11,0.4)" }} />
        ))}
      </motion.div>

      {/* Status badge */}
      <motion.div initial={{ opacity:0,y:8 }} animate={{ opacity:1,y:0 }} transition={{ delay:.2 }}
        className="flex items-center gap-2 px-4 py-1.5 rounded-full mb-3"
        style={{ background:"rgba(245,158,11,0.15)", border:"1px solid rgba(245,158,11,0.4)" }}>
        <Clock className="w-3.5 h-3.5" style={{ color:"#FBBF24" }} />
        <span className="text-xs font-bold" style={{ color:"#FBBF24" }}>{t("onboard.pendingStatus")}</span>
      </motion.div>

      {/* Title */}
      <motion.div initial={{ opacity:0,y:8 }} animate={{ opacity:1,y:0 }} transition={{ delay:.25 }} className="text-center mb-4">
        <h2 className="text-xl font-extrabold text-white mb-1">{t("onboard.pendingTitle")}</h2>
        <div className="flex items-center justify-center gap-2 mb-2">
          <div className="w-6 h-6 rounded-lg flex items-center justify-center" style={{ background:`rgba(${hexToRgb(color)},0.2)` }}>
            <SectorIcon className="w-3.5 h-3.5" style={{ color }} />
          </div>
          <span className="text-sm font-semibold" style={{ color:"#60A5FA" }}>
            {businessName || t(`onboard.sector_${sectorKey}`)}
          </span>
        </div>
        <p className="text-sm leading-relaxed" style={{ color:"#94A3B8" }}>{t("onboard.pendingMsg")}</p>
      </motion.div>

      {/* Review pipeline */}
      <motion.div initial={{ opacity:0,y:8 }} animate={{ opacity:1,y:0 }} transition={{ delay:.35 }}
        className="w-full rounded-2xl p-4 mb-4 space-y-3"
        style={{ background:"rgba(255,255,255,0.04)", border:"1px solid rgba(255,255,255,0.08)" }}>
        {steps.map((step, i) => (
          <div key={i} className="flex items-center gap-3">
            <div className={`w-7 h-7 rounded-full flex items-center justify-center flex-shrink-0 ${step.done?"":"opacity-40"}`}
              style={step.done ? { background:"rgba(16,185,129,0.2)", border:"1px solid rgba(52,211,153,0.5)" }
                : { background:"rgba(255,255,255,0.06)", border:"1px solid rgba(255,255,255,0.15)" }}>
              {step.done
                ? <Check className="w-3.5 h-3.5" style={{ color:"#34D399" }} />
                : <span className="text-[10px] font-bold" style={{ color:"rgba(255,255,255,0.4)" }}>{i+1}</span>
              }
            </div>
            <div className="flex-1">
              <p className="text-xs font-semibold" style={{ color: step.done?"#FFFFFF":"rgba(255,255,255,0.4)" }}>
                {step.ku}
              </p>
              {!step.done && i===1 && (
                <motion.div animate={{ opacity:[0.4,1,0.4] }} transition={{ duration:2, repeat:Infinity }}
                  className="text-[10px] mt-0.5" style={{ color:"#F59E0B" }}>
                  ● {t("onboard.inProgress")}
                </motion.div>
              )}
            </div>
          </div>
        ))}
      </motion.div>

      {/* Contact card */}
      <motion.div initial={{ opacity:0,y:8 }} animate={{ opacity:1,y:0 }} transition={{ delay:.45 }}
        className="w-full rounded-2xl p-4 flex items-start gap-3"
        style={{ background:"rgba(59,130,246,0.08)", border:"1px solid rgba(59,130,246,0.2)" }}>
        <Globe className="w-5 h-5 flex-shrink-0 mt-0.5" style={{ color:"#60A5FA" }} />
        <div>
          <p className="text-xs font-bold text-white mb-0.5">{t("onboard.pendingContact")}</p>
          <p className="text-xs" style={{ color:"#93C5FD" }}>{t("onboard.pendingNote")}</p>
