import { pgTable, serial, text, timestamp, jsonb } from "drizzle-orm/pg-core";

export const businessRegistrationsTable = pgTable("business_registrations", {
  id: serial("id").primaryKey(),
  sectorKey:       text("sector_key").notNull(),
  sectorGroup:     text("sector_group").notNull(),
  businessName:    text("business_name").notNull(),
  email:           text("email"),
  mobile:          text("mobile").notNull().default(""),
  governorate:     text("governorate"),
  city:            text("city"),
  address:         text("address"),
  extraData:       jsonb("extra_data"),
  status: text("status", {
    enum: ["pending", "approved", "rejected", "suspended", "more_docs_needed"],
  }).notNull().default("pending"),
  rejectionReason: text("rejection_reason"),
  submittedAt:     timestamp("submitted_at").notNull().defaultNow(),
  reviewedAt:      timestamp("reviewed_at"),
  reviewedBy:      text("reviewed_by"),
});

export type BusinessRegistration = typeof businessRegistrationsTable.$inferSelect;
export type InsertBusinessRegistration = typeof businessRegistrationsTable.$inferInsert;

import { Router, type IRouter } from "express";
import { db } from "@workspace/db";
import { businessRegistrationsTable } from "@workspace/db/src/schema/registrations";
import { eq, desc } from "drizzle-orm";
import { z } from "zod";
import { requireAdmin } from "../middlewares/auth";

const router: IRouter = Router();

/* ─── POST /registrations ─── public (no auth — new businesses register) ── */
router.post("/registrations", async (req, res): Promise<void> => {
  try {
    const schema = z.object({
      sectorKey:    z.string().min(1),
      sectorGroup:  z.string().min(1),
      businessName: z.string().min(1),
      email:        z.string().optional(),
      mobile:       z.string().optional(),
      governorate:  z.string().optional(),
      city:         z.string().optional(),
      address:      z.string().optional(),
      extraData:    z.record(z.unknown()).optional(),
    });
    const body = schema.parse(req.body);
    const [reg] = await db
      .insert(businessRegistrationsTable)
      .values({
        sectorKey:    body.sectorKey,
        sectorGroup:  body.sectorGroup,
        businessName: body.businessName,
        email:        body.email,
        mobile:       body.mobile ?? "",
        governorate:  body.governorate,
        city:         body.city,
        address:      body.address,
        extraData:    body.extraData ?? {},
      })
      .returning();
    res.status(201).json(reg);
  } catch (err) {
    req.log.error({ err }, "Failed to submit registration");
    res.status(400).json({ message: "داتاکان هەڵەن" });
  }
});

/* ─── GET /admin/registrations ─── admin only ─────────────────────── */
router.get("/admin/registrations", requireAdmin, async (req, res): Promise<void> => {
  try {
    const rows = await db
      .select()
      .from(businessRegistrationsTable)
      .orderBy(desc(businessRegistrationsTable.submittedAt));
    res.json(rows);
  } catch (err) {
    req.log.error({ err }, "Failed to fetch registrations");
    res.status(500).json({ message: "هەڵەیەک ڕوویدا" });
  }
});

/* ─── PATCH /admin/registrations/:id/status ─── admin only ─────────── */
router.patch("/admin/registrations/:id/status", requireAdmin, async (req, res): Promise<void> => {
  try {
    const id = parseInt(String(req.params.id));
    const schema = z.object({
      status: z.enum(["pending", "approved", "rejected", "suspended", "more_docs_needed"]),
      rejectionReason: z.string().optional(),
    });
    const body = schema.parse(req.body);
    const [reg] = await db
      .update(businessRegistrationsTable)
      .set({
        status:          body.status,
        rejectionReason: body.rejectionReason ?? null,
        reviewedAt:      new Date(),
        reviewedBy:      req.user?.name ?? req.user?.username,
      })
      .where(eq(businessRegistrationsTable.id, id))
      .returning();
    if (!reg) { res.status(404).json({ message: "داواکاری نەدۆزرایەوە" }); return; }
    res.json(reg);
  } catch (err) {
    req.log.error({ err }, "Failed to update registration status");
    res.status(400).json({ message: "داتاکان هەڵەن" });
  }
});

/* ─── POST /admin/registrations/seed ─── admin only (demo data) ──── */
router.post("/admin/registrations/seed", requireAdmin, async (req, res): Promise<void> => {
  try {
    const existing = await db.select().from(businessRegistrationsTable);
    if (existing.length >= 3) {
      res.json({ message: "Demo data already present", count: existing.length });
      return;
    }
    const seeds = [
      {
        sectorKey: "distributor", sectorGroup: "enterprise",
        businessName: "Kurdistan Traders Group",
        email: "info@kurdtraders.iq", mobile: "07501234567",
        governorate: "erbil", city: "هەولێر",
        address: "36.1911, 44.0092 — سانتەر سیتی، هەولێر",
        extraData: {
          licenseNumber: "TRD-2024-00421",
          managerName: "سردار عومەر",
          brands: "Nestle, P&G, Unilever",
          productCategories: "خواردن، بەرهەمی خانە",
          productionCapacity: "ناوەبەند",
          deliveryArea: "both",
          whatsapp: "07501234567",
        },
        status: "pending" as const,
      },
      {
        sectorKey: "restaurant", sectorGroup: "retail",
        businessName: "چێشتخانەی سۆفی",
        email: "sofi@rest.iq", mobile: "07701987654",
        governorate: "sulaymaniyah", city: "سلێمانی",
        address: "35.5571, 45.4350 — گەڕەکی ئازادی، سلێمانی",
        extraData: {
          managerName: "سۆفیا ئەحمەد",
          leadTime: 2,
        },
        status: "pending" as const,
      },
      {
        sectorKey: "delivery", sectorGroup: "delivery",
        businessName: "StarExpress Delivery",
        email: "ops@starex.iq", mobile: "07001122334",
        governorate: "duhok", city: "دهۆک",
        address: "36.8670, 42.9850 — ناوەندی دهۆک",
        extraData: {
          companyReg: "DEL-2023-0987",
          nationalId: "1234567890123",
          truckSizes: ["ئەتیکۆ", "پیکاب", "کیا"],
          coverageArea: "both",
          numTrucks: "12",
        },
        status: "pending" as const,
      },
      {
        sectorKey: "pharmacy", sectorGroup: "standard",
        businessName: "دەرمانخانەی شیفا",
        email: "shifa@pharma.iq", mobile: "07801234321",
        governorate: "kirkuk", city: "کەرکوک",
        address: "35.4682, 44.3922 — گەڕەکی شۆڕجە، کەرکوک",
        extraData: {
          managerName: "ئارام کامال",
        },
        status: "approved" as const,
        reviewedBy: "admin",
        reviewedAt: new Date(Date.now() - 86400000),
      },
      {
        sectorKey: "manufacturer", sectorGroup: "enterprise",
