import { useState, useCallback } from "react";
import { useTranslation } from "react-i18next";
import i18n from "@/i18n";
import { motion, AnimatePresence } from "framer-motion";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import {
  Search, Filter, RefreshCw, Eye, CheckCircle2, XCircle,
  FileText, Clock, AlertTriangle, Layers, Truck, Share2,
  Factory, HeartPulse, ShoppingBag, UtensilsCrossed, Building2,
  ShoppingCart, Pill, Briefcase, X, ChevronRight, MapPin,
  Check, Globe, User, Mail, Phone, ExternalLink, Download,
  Database, Play, ChevronDown, Slash, Lock,
} from "lucide-react";

/* ─── Constants ─────────────────────────────────────────────────────── */
const API_BASE = import.meta.env.VITE_API_URL ?? "/api";
const getToken = () => localStorage.getItem("pos_auth_token") ?? "";

const LANGUAGES = [
  { code: "ku", label: "کوردی" },
  { code: "ar", label: "عربی" },
  { code: "en", label: "EN" },
];

const SECTOR_META: Record<string, { icon: any; color: string }> = {
  distributor:  { icon: Share2,          color: "#F59E0B" },
  manufacturer: { icon: Factory,         color: "#EF4444" },
  hospital:     { icon: HeartPulse,      color: "#EC4899" },
  supermarket:  { icon: ShoppingBag,     color: "#8B5CF6" },
  retail_shop:  { icon: ShoppingCart,    color: "#A855F7" },
  restaurant:   { icon: UtensilsCrossed, color: "#F97316" },
  hotel:        { icon: Building2,       color: "#06B6D4" },
  pharmacy:     { icon: Pill,            color: "#22C55E" },
  delivery:     { icon: Truck,           color: "#10B981" },
  office:       { icon: Briefcase,       color: "#3B82F6" },
  other:        { icon: Layers,          color: "#6B7280" },
};

const STATUS_META: Record<string, { color: string; bg: string; border: string; icon: any; labelKey: string }> = {
  pending:         { color: "#FBBF24", bg: "rgba(245,158,11,0.15)", border: "rgba(245,158,11,0.4)", icon: Clock,        labelKey: "verify.statusPending" },
  approved:        { color: "#34D399", bg: "rgba(16,185,129,0.15)", border: "rgba(16,185,129,0.4)", icon: CheckCircle2, labelKey: "verify.statusApproved" },
  rejected:        { color: "#F87171", bg: "rgba(239,68,68,0.15)",  border: "rgba(239,68,68,0.4)",  icon: XCircle,      labelKey: "verify.statusRejected" },
  suspended:       { color: "#94A3B8", bg: "rgba(100,116,139,0.15)", border: "rgba(100,116,139,0.4)", icon: Slash,       labelKey: "verify.statusSuspended" },
  more_docs_needed:{ color: "#60A5FA", bg: "rgba(59,130,246,0.15)", border: "rgba(59,130,246,0.4)", icon: AlertTriangle, labelKey: "verify.statusMoreDocs" },
};

const DOCS_BY_GROUP: Record<string, { key: string; required: boolean }[]> = {
  enterprise: [
    { key: "uploadCommercialReg", required: true },
    { key: "uploadManufacturingLicense", required: true },
    { key: "uploadOwnerID", required: true },
    { key: "uploadISO", required: false },
    { key: "uploadCatalog", required: false },
  ],
  retail:   [{ key: "uploadOwnerID", required: true }],
  delivery: [{ key: "uploadOwnerID", required: true }, { key: "uploadCommercialReg", required: true }],
  standard: [{ key: "uploadOwnerID", required: true }],
};

/* ─── Types ─────────────────────────────────────────────────────────── */
interface Registration {
  id: number;
  sectorKey: string;
  sectorGroup: string;
  businessName: string;
  email?: string;
  mobile: string;
  governorate?: string;
  city?: string;
  address?: string;
  extraData?: Record<string, any>;
  status: "pending" | "approved" | "rejected" | "suspended" | "more_docs_needed";
  rejectionReason?: string;
  submittedAt: string;
  reviewedAt?: string;
  reviewedBy?: string;
}

/* ─── Glass tokens ───────────────────────────────────────────────────── */
const glass = {
  card: {
    background: "rgba(255,255,255,0.05)",
    backdropFilter: "blur(20px)",
    WebkitBackdropFilter: "blur(20px)",
    border: "1px solid rgba(255,255,255,0.10)",
    boxShadow: "0 4px 32px rgba(0,0,0,0.4)",
  } as React.CSSProperties,
  input: {
    background: "rgba(0,0,0,0.25)",
    border: "1px solid rgba(255,255,255,0.12)",
    color: "#FFFFFF",
    borderRadius: "0.75rem",
  } as React.CSSProperties,
};

/* ─── API helpers ────────────────────────────────────────────────────── */
async function fetchRegistrations(): Promise<Registration[]> {
  const res = await fetch(`${API_BASE}/admin/registrations`, {
    headers: { Authorization: `Bearer ${getToken()}` },
  });
  if (!res.ok) throw new Error("Failed to load registrations");
  return res.json();
}

async function seedDemo(token: string): Promise<void> {
  await fetch(`${API_BASE}/admin/registrations/seed`, {
    method: "POST",
    headers: { Authorization: `Bearer ${token}` },
  });
}

/* ─── StatusBadge ────────────────────────────────────────────────────── */
function StatusBadge({ status }: { status: string }) {
  const { t } = useTranslation();
  const m = STATUS_META[status] ?? STATUS_META.pending;
  const Icon = m.icon;
  return (
    <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-bold whitespace-nowrap"
      style={{ background: m.bg, border: `1px solid ${m.border}`, color: m.color }}>
      <Icon className="w-3 h-3" />
      {t(m.labelKey)}
    </span>
  );
}

/* ─── SectorChip ─────────────────────────────────────────────────────── */
function SectorChip({ sectorKey }: { sectorKey: string }) {
  const { t } = useTranslation();
  const m = SECTOR_META[sectorKey] ?? SECTOR_META.other;
  const Icon = m.icon;
  return (
    <span className="inline-flex items-center gap-1.5 px-2 py-1 rounded-lg text-[11px] font-semibold"
      style={{ background: `${m.color}1A`, border: `1px solid ${m.color}44`, color: m.color }}>
      <Icon className="w-3 h-3" />
      {t(`onboard.sector_${sectorKey}`, sectorKey)}
    </span>
  );
}

/* ─── StatsCard ──────────────────────────────────────────────────────── */
function StatsCard({ count, labelKey, color, icon: Icon }: { count: number; labelKey: string; color: string; icon: any }) {
  const { t } = useTranslation();
  return (
    <div className="flex items-center gap-3 px-4 py-3 rounded-2xl flex-1 min-w-[120px]"
      style={{ background: `${color}0F`, border: `1px solid ${color}33` }}>
      <div className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0"
        style={{ background: `${color}22` }}>
        <Icon className="w-5 h-5" style={{ color }} />
      </div>
      <div>
        <p className="text-2xl font-black" style={{ color }}>{count}</p>
        <p className="text-[11px] font-medium" style={{ color: "rgba(255,255,255,0.5)" }}>{t(labelKey)}</p>
      </div>
    </div>
  );
}

/* ─── GPSMapDisplay ──────────────────────────────────────────────────── */
function GPSMapDisplay({ address }: { address?: string }) {
  const { t } = useTranslation();
  if (!address) return (
    <div className="flex flex-col items-center justify-center gap-2 rounded-xl py-8" style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.08)" }}>
      <MapPin className="w-8 h-8" style={{ color: "rgba(255,255,255,0.2)" }} />
      <p className="text-xs" style={{ color: "rgba(255,255,255,0.3)" }}>{t("verify.gpsNotAvailable")}</p>
    </div>
  );

  const coordMatch = address.match(/(-?\d+\.\d+)\s*,\s*(-?\d+\.\d+)/);
  const lat = coordMatch ? parseFloat(coordMatch[1]) : 36.1911;
  const lng = coordMatch ? parseFloat(coordMatch[2]) : 44.0092;
  const delta = 0.05;
  const mapUrl = `https://www.openstreetmap.org/export/embed.html?bbox=${lng-delta}%2C${lat-delta}%2C${lng+delta}%2C${lat+delta}&layer=mapnik&marker=${lat}%2C${lng}`;
  const linkUrl = `https://www.openstreetmap.org/?mlat=${lat}&mlon=${lng}#map=15/${lat}/${lng}`;

  return (
    <div className="rounded-xl overflow-hidden" style={{ border: "1px solid rgba(255,255,255,0.10)" }}>
      <iframe src={mapUrl} width="100%" height="200" style={{ border: 0, display: "block" }} title="GPS Location" />
      <div className="flex items-center justify-between px-3 py-2"
        style={{ background: "rgba(0,0,0,0.4)", borderTop: "1px solid rgba(255,255,255,0.08)" }}>
        <div className="flex items-center gap-2">
          <MapPin className="w-3.5 h-3.5" style={{ color: "#60A5FA" }} />
          <span className="text-[11px] text-white/60 truncate max-w-[240px]">{address}</span>
        </div>
        <a href={linkUrl} target="_blank" rel="noreferrer"
          className="flex items-center gap-1 text-[11px] font-semibold transition-opacity hover:opacity-80"
          style={{ color: "#60A5FA" }}>
          <ExternalLink className="w-3 h-3" /> OSM
        </a>
      </div>
    </div>
  );
}

/* ─── DocumentMatrix ─────────────────────────────────────────────────── */
function DocumentMatrix({ sectorGroup }: { sectorGroup: string }) {
  const { t } = useTranslation();
  const docs = DOCS_BY_GROUP[sectorGroup] ?? DOCS_BY_GROUP.standard;
  return (
    <div className="grid grid-cols-2 sm:grid-cols-3 gap-2.5">
      {docs.map(({ key, required }) => (
        <div key={key} className="flex flex-col items-center gap-2 p-3 rounded-xl text-center"
          style={{ background: "rgba(255,255,255,0.04)", border: `1px dashed ${required ? "rgba(239,68,68,0.4)" : "rgba(255,255,255,0.12)"}` }}>
          <div className="w-9 h-9 rounded-xl flex items-center justify-center"
            style={{ background: required ? "rgba(239,68,68,0.12)" : "rgba(255,255,255,0.06)" }}>
            <FileText className="w-5 h-5" style={{ color: required ? "#FCA5A5" : "rgba(255,255,255,0.3)" }} />
          </div>
          <p className="text-[10px] font-semibold leading-tight" style={{ color: "rgba(255,255,255,0.6)" }}>
            {t(`onboard.${key}`, key)}
          </p>
          <span className={`text-[9px] px-1.5 py-0.5 rounded-full font-bold ${required
            ? "text-red-300 border-red-400/30 bg-red-400/10 border"
            : "text-slate-400 border-slate-600/30 bg-slate-600/10 border"}`}>
            {required ? t("verify.docRequired") : t("verify.docOptional")}
          </span>
        </div>
      ))}
    </div>
  );
}

/* ─── SectorFieldsDisplay ────────────────────────────────────────────── */
function SectorFieldsDisplay({ sectorGroup, extraData }: { sectorGroup: string; extraData?: Record<string, any> }) {
  const { t } = useTranslation();
  if (!extraData) return null;

  const fieldGroups: Record<string, string[]> = {
    enterprise: ["licenseNumber", "managerName", "brands", "productCategories", "productionCapacity", "deliveryArea", "whatsapp"],
    retail:     ["managerName", "leadTime"],
    delivery:   ["companyReg", "nationalId", "truckSizes", "coverageArea", "numTrucks"],
    standard:   ["managerName"],
  };
  const fields = fieldGroups[sectorGroup] ?? [];

  const labelMap: Record<string, string> = {
    licenseNumber: "onboard.licenseNumber", managerName: "onboard.managerName",
    brands: "onboard.brands", productCategories: "onboard.productCategories",
    productionCapacity: "onboard.productionCapacity", deliveryArea: "onboard.deliveryArea",
    whatsapp: "onboard.whatsapp", leadTime: "onboard.leadTime",
    companyReg: "onboard.companyReg", nationalId: "onboard.nationalId",
    truckSizes: "onboard.truckSizes", coverageArea: "onboard.coverageArea",
    numTrucks: "onboard.numTrucks",
  };

  const renderValue = (key: string, val: any) => {
    if (val === undefined || val === null || val === "") return "—";
    if (key === "leadTime") return `${val} ${t("onboard.days")}`;
    if (key === "deliveryArea" || key === "coverageArea") {
      const areaMap: Record<string, string> = { inner: t("onboard.deliveryAreaInner"), outer: t("onboard.deliveryAreaOuter"), both: t("onboard.deliveryAreaBoth") };
      return areaMap[val] ?? val;
    }
    if (Array.isArray(val)) return val.join(" • ");
    return String(val);
  };

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
      {fields.map(key => {
        const val = extraData[key];
        if (val === undefined || val === null) return null;
        return (
          <div key={key} className="p-3 rounded-xl" style={{ background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.07)" }}>
            <p className="text-[10px] font-bold uppercase tracking-wide mb-1" style={{ color: "#64748B" }}>
              {t(labelMap[key] ?? key, key)}
            </p>
            <p className="text-sm font-semibold text-white break-all">{renderValue(key, val)}</p>
          </div>
        );
      })}
    </div>
  );
}

/* ─── Review Modal ───────────────────────────────────────────────────── */
function ReviewModal({ reg, onClose, onStatusChange }: {
  reg: Registration;
  onClose: () => void;
  onStatusChange: (id: number, status: string, reason?: string) => void;
}) {
  const { t } = useTranslation();
  const [tab, setTab] = useState<"info" | "docs" | "map" | "actions">("info");
  const [action, setAction] = useState<string>("");
  const [reason, setReason] = useState(reg.rejectionReason ?? "");
  const [saving, setSaving] = useState(false);

  const sectorMeta = SECTOR_META[reg.sectorKey] ?? SECTOR_META.other;
  const SectorIcon = sectorMeta.icon;

  const handleAction = async () => {
    if (!action) return;
    setSaving(true);
    await onStatusChange(reg.id, action, action === "rejected" ? reason : undefined);
    setSaving(false);
    setAction("");
  };

  const TABS = [
    { key: "info",    labelKey: "verify.tabInfo",    icon: User },
    { key: "docs",    labelKey: "verify.tabDocs",    icon: FileText },
    { key: "map",     labelKey: "verify.tabMap",     icon: MapPin },
    { key: "actions", labelKey: "verify.tabActions", icon: CheckCircle2 },
  ];

  return (
    <motion.div
      initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
      className="fixed inset-0 z-50 flex items-center justify-end"
      style={{ backdropFilter: "blur(6px)", WebkitBackdropFilter: "blur(6px)", background: "rgba(0,0,0,0.6)" }}
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <motion.div
        initial={{ x: "100%" }} animate={{ x: 0 }} exit={{ x: "100%" }}
        transition={{ type: "spring", stiffness: 280, damping: 28 }}
        className="h-full w-full max-w-xl flex flex-col overflow-hidden"
        style={{ ...glass.card, borderRadius: "24px 0 0 24px", border: "1px solid rgba(255,255,255,0.12)" }}>

        {/* Modal Header */}
        <div className="flex items-center gap-4 px-6 py-5 flex-shrink-0"
          style={{ borderBottom: "1px solid rgba(255,255,255,0.08)" }}>
          <div className="w-12 h-12 rounded-2xl flex items-center justify-center flex-shrink-0"
            style={{ background: `${sectorMeta.color}22`, border: `1.5px solid ${sectorMeta.color}44` }}>
            <SectorIcon className="w-6 h-6" style={{ color: sectorMeta.color }} />
          </div>
          <div className="flex-1 min-w-0">
            <h2 className="text-base font-bold text-white leading-tight truncate">{reg.businessName}</h2>
            <div className="flex items-center gap-2 mt-1 flex-wrap">
              <SectorChip sectorKey={reg.sectorKey} />
              <StatusBadge status={reg.status} />
            </div>
          </div>
          <button onClick={onClose} className="w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0 transition-all hover:bg-white/10" style={{ color: "#64748B" }}>
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Quick info strip */}
        <div className="grid grid-cols-3 gap-px flex-shrink-0" style={{ borderBottom: "1px solid rgba(255,255,255,0.08)", background: "rgba(255,255,255,0.04)" }}>
          {[
            { icon: Mail, value: reg.email || "—" },
            { icon: Phone, value: reg.mobile || "—" },
            { icon: MapPin, value: `${reg.governorate ? t(`register.provinces.${reg.governorate}`, reg.governorate) : ""}${reg.city ? ` · ${reg.city}` : ""}` || "—" },
          ].map(({ icon: Icon, value }, i) => (
            <div key={i} className="flex items-center gap-2 px-4 py-3" style={{ background: "rgba(0,0,0,0.2)" }}>
              <Icon className="w-3.5 h-3.5 flex-shrink-0" style={{ color: "#60A5FA" }} />
              <span className="text-xs text-white/60 truncate">{value}</span>
            </div>
          ))}
        </div>

        {/* Tabs */}
        <div className="flex gap-1 px-4 py-3 flex-shrink-0" style={{ borderBottom: "1px solid rgba(255,255,255,0.08)" }}>
          {TABS.map(({ key, labelKey, icon: Icon }) => (
            <button key={key} onClick={() => setTab(key as any)}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold transition-all flex-1 justify-center"
              style={tab === key
                ? { background: "rgba(59,130,246,0.25)", color: "#FFFFFF", border: "1px solid rgba(99,179,255,0.4)" }
                : { background: "transparent", color: "rgba(255,255,255,0.45)", border: "1px solid transparent" }}>
              <Icon className="w-3.5 h-3.5" />
              <span className="hidden sm:inline">{t(labelKey)}</span>
            </button>
          ))}
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto px-6 py-5 space-y-4">
          <AnimatePresence mode="wait">
            {tab === "info" && (
              <motion.div key="info" initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }}>
                <p className="text-xs font-bold uppercase tracking-widest mb-3" style={{ color: "#60A5FA" }}>
                  {t("verify.sectorFields")}
                </p>
                <SectorFieldsDisplay sectorGroup={reg.sectorGroup} extraData={reg.extraData} />
                {reg.reviewedAt && (
                  <div className="mt-4 p-3 rounded-xl" style={{ background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.07)" }}>
                    <p className="text-[11px]" style={{ color: "#64748B" }}>
                      {t("verify.reviewedAt")}: <span className="text-white/60">{new Date(reg.reviewedAt).toLocaleDateString()}</span>
                      {reg.reviewedBy && <> · <span className="text-white/60">{reg.reviewedBy}</span></>}
                    </p>
                    {reg.rejectionReason && (
                      <p className="text-[11px] mt-1.5 text-red-400">{reg.rejectionReason}</p>
                    )}
                  </div>
                )}
              </motion.div>
            )}

            {tab === "docs" && (
              <motion.div key="docs" initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }}>
                <p className="text-xs font-bold uppercase tracking-widest mb-3" style={{ color: "#60A5FA" }}>
                  {t("verify.documents")}
                </p>
                <DocumentMatrix sectorGroup={reg.sectorGroup} />
                <div className="mt-4 p-3 rounded-xl flex items-start gap-2.5"
                  style={{ background: "rgba(245,158,11,0.08)", border: "1px solid rgba(245,158,11,0.25)" }}>
                  <AlertTriangle className="w-4 h-4 flex-shrink-0 mt-0.5" style={{ color: "#FBBF24" }} />
                  <p className="text-xs" style={{ color: "#FDE68A" }}>{t("verify.docNote")}</p>
                </div>
              </motion.div>
            )}

            {tab === "map" && (
              <motion.div key="map" initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }}>
                <p className="text-xs font-bold uppercase tracking-widest mb-3" style={{ color: "#60A5FA" }}>
                  {t("verify.gpsLocation")}
                </p>
                <GPSMapDisplay address={reg.address} />
                {reg.address && (
                  <div className="mt-3 p-3 rounded-xl" style={{ background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.07)" }}>
                    <p className="text-[11px] text-white/50">{reg.address}</p>
                  </div>
                )}
              </motion.div>
            )}

            {tab === "actions" && (
              <motion.div key="actions" initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="space-y-3">
                <p className="text-xs font-bold uppercase tracking-widest mb-4" style={{ color: "#60A5FA" }}>
                  {t("verify.selectAction")}
                </p>

                {[
                  { key: "approved",         icon: CheckCircle2, color: "#10B981", labelKey: "verify.approve",     desc: "verify.approveDesc" },
                  { key: "rejected",         icon: XCircle,      color: "#EF4444", labelKey: "verify.reject",      desc: "verify.rejectDesc" },
                  { key: "more_docs_needed", icon: FileText,     color: "#3B82F6", labelKey: "verify.requestDocs", desc: "verify.requestDocsDesc" },
                  { key: reg.status === "suspended" ? "pending" : "suspended",
                    icon: reg.status === "suspended" ? Play : Lock,
                    color: reg.status === "suspended" ? "#10B981" : "#64748B",
                    labelKey: reg.status === "suspended" ? "verify.reactivate" : "verify.suspend",
                    desc: reg.status === "suspended" ? "verify.reactivateDesc" : "verify.suspendDesc",
                  },
                ].map(({ key, icon: Icon, color, labelKey, desc }) => (
                  <button key={key} type="button" onClick={() => setAction(action === key ? "" : key)}
                    className="w-full flex items-center gap-3 p-3.5 rounded-2xl text-start transition-all"
                    style={action === key
                      ? { background: `${color}22`, border: `2px solid ${color}66`, boxShadow: `0 0 16px ${color}22` }
                      : { background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.10)" }}>
                    <div className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0"
                      style={{ background: `${color}22` }}>
                      <Icon className="w-5 h-5" style={{ color }} />
                    </div>
                    <div className="flex-1">
                      <p className="text-sm font-bold text-white">{t(labelKey)}</p>
                      <p className="text-[11px] mt-0.5" style={{ color: "rgba(255,255,255,0.45)" }}>{t(desc)}</p>
                    </div>
                    <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-all`}
                      style={action === key ? { background: color, borderColor: color } : { borderColor: "rgba(255,255,255,0.2)" }}>
                      {action === key && <Check className="w-3 h-3 text-white" />}
                    </div>
                  </button>
                ))}

                <AnimatePresence>
                  {action === "rejected" && (
                    <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }} exit={{ opacity: 0, height: 0 }}>
                      <label className="block text-xs font-semibold mb-2 uppercase tracking-wide" style={{ color: "#E2E8F0" }}>
                        {t("verify.rejectionReason")}
                      </label>
                      <textarea value={reason} onChange={e => setReason(e.target.value)} rows={3}
                        placeholder={t("verify.rejectionReasonPh")}
                        className="w-full px-3.5 py-2.5 rounded-xl text-sm text-white placeholder-[#64748B] resize-none outline-none"
                        style={{ ...glass.input }} />
                    </motion.div>
                  )}
                </AnimatePresence>

                {action && (
                  <motion.button
                    initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }}
                    type="button" onClick={handleAction} disabled={saving}
                    className="w-full py-3.5 rounded-2xl font-bold text-sm flex items-center justify-center gap-2 transition-all"
                    style={{ background: action === "approved" ? "linear-gradient(135deg,#059669,#10B981)" :
                      action === "rejected" ? "linear-gradient(135deg,#DC2626,#EF4444)" :
                      action === "more_docs_needed" ? "linear-gradient(135deg,#1D4ED8,#3B82F6)" :
                      "linear-gradient(135deg,#334155,#475569)",
                      color: "#FFFFFF", boxShadow: "0 4px 20px rgba(0,0,0,0.4)" }}>
                    {saving
                      ? <><div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />{t("verify.saving")}</>
                      : <><Check className="w-4 h-4" />{t("verify.confirm")}</>
                    }
                  </motion.button>
                )}
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between px-6 py-4 flex-shrink-0"
          style={{ borderTop: "1px solid rgba(255,255,255,0.08)", background: "rgba(0,0,0,0.2)" }}>
          <p className="text-[11px]" style={{ color: "rgba(255,255,255,0.3)" }}>
            ID #{reg.id} · {new Date(reg.submittedAt).toLocaleDateString()}
          </p>
          <button onClick={onClose} className="text-xs font-semibold px-3 py-1.5 rounded-xl transition-all hover:bg-white/10"
            style={{ color: "#64748B" }}>
            {t("verify.close")}
          </button>
        </div>
      </motion.div>
    </motion.div>
  );
}

