/* MAIN ADMIN VERIFICATION PAGE                                           */
/* ═══════════════════════════════════════════════════════════════════════ */
export default function AdminVerification() {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [lang, setLang] = useState(i18n.language);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [sectorFilter, setSectorFilter] = useState("all");
  const [selected, setSelected] = useState<Registration | null>(null);
  const [seeding, setSeeding] = useState(false);

  const { data: registrations = [], isLoading, refetch } = useQuery({
    queryKey: ["admin-registrations"],
    queryFn: fetchRegistrations,
    refetchInterval: 30000,
  });

  const updateStatusMutation = useMutation({
    mutationFn: async ({ id, status, rejectionReason }: { id: number; status: string; rejectionReason?: string }) => {
      const res = await fetch(`${API_BASE}/admin/registrations/${id}/status`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${getToken()}` },
        body: JSON.stringify({ status, rejectionReason }),
      });
      if (!res.ok) throw new Error("Failed to update");
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["admin-registrations"] });
      setSelected(prev => {
        if (!prev) return null;
        const updated = registrations.find(r => r.id === prev.id);
        return updated ?? null;
      });
    },
  });

  const handleStatusChange = useCallback(async (id: number, status: string, reason?: string) => {
    await updateStatusMutation.mutateAsync({ id, status, rejectionReason: reason });
    setSelected(prev => prev ? { ...prev, status: status as any, rejectionReason: reason, reviewedAt: new Date().toISOString() } : null);
  }, [updateStatusMutation]);

  const handleSeed = async () => {
    setSeeding(true);
    try {
      await seedDemo(getToken());
      await refetch();
    } finally {
      setSeeding(false);
    }
  };

  const switchLang = (code: string) => {
    i18n.changeLanguage(code);
    setLang(code);
    document.documentElement.dir = code === "ku" || code === "ar" ? "rtl" : "ltr";
  };

  /* Stats */
  const pending   = registrations.filter(r => r.status === "pending").length;
  const approved  = registrations.filter(r => r.status === "approved").length;
  const rejected  = registrations.filter(r => r.status === "rejected").length;
  const suspended = registrations.filter(r => r.status === "suspended").length;

  /* Filtered list */
  const filtered = registrations.filter(r => {
    const q = search.toLowerCase();
    const matchSearch = !q || r.businessName.toLowerCase().includes(q) || r.mobile.includes(q) || r.sectorKey.includes(q);
    const matchStatus = statusFilter === "all" || r.status === statusFilter;
    const matchSector = sectorFilter === "all" || r.sectorKey === sectorFilter;
    return matchSearch && matchStatus && matchSector;
  });

  return (
    <div className="min-h-screen p-0" style={{ background: "linear-gradient(135deg,#020C1C 0%,#0A1628 50%,#081022 100%)" }}>
      <div className="max-w-6xl mx-auto px-4 py-6 space-y-5">

        {/* ── Page Header ── */}
        <div className="flex items-center justify-between flex-wrap gap-3">
          <div>
            <h1 className="text-2xl font-black text-white leading-tight">{t("verify.title")}</h1>
            <p className="text-sm mt-0.5" style={{ color: "#64748B" }}>{t("verify.subtitle")}</p>
          </div>
          <div className="flex items-center gap-2 flex-wrap">
            {/* Language switcher */}
            <div className="flex items-center gap-1 px-1 py-1 rounded-xl" style={{ background: "rgba(255,255,255,0.06)", border: "1px solid rgba(255,255,255,0.10)" }}>
              {LANGUAGES.map(l => (
                <button key={l.code} onClick={() => switchLang(l.code)}
                  className="px-2.5 py-1 rounded-lg text-xs font-semibold transition-all"
                  style={lang === l.code
                    ? { background: "rgba(59,130,246,0.3)", color: "#FFFFFF", border: "1px solid rgba(99,179,255,0.4)" }
                    : { background: "transparent", color: "rgba(255,255,255,0.4)", border: "1px solid transparent" }}>
                  {l.label}
                </button>
              ))}
            </div>
            {/* Load Demo Data */}
            <button onClick={handleSeed} disabled={seeding}
              className="flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-semibold transition-all"
              style={{ background: "rgba(16,185,129,0.15)", border: "1px solid rgba(16,185,129,0.35)", color: "#34D399" }}>
              {seeding
                ? <div className="w-3.5 h-3.5 border-2 border-emerald-300/30 border-t-emerald-300 rounded-full animate-spin" />
                : <Database className="w-3.5 h-3.5" />
              }
              {t("verify.seedDemo")}
            </button>
            {/* Refresh */}
            <button onClick={() => refetch()}
              className="flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-semibold transition-all"
              style={{ background: "rgba(255,255,255,0.06)", border: "1px solid rgba(255,255,255,0.12)", color: "#94A3B8" }}>
              <RefreshCw className="w-3.5 h-3.5" />
              {t("verify.refresh")}
            </button>
          </div>
        </div>

        {/* ── Stats Row ── */}
        <div className="flex gap-3 flex-wrap">
          <StatsCard count={pending}   labelKey="verify.statsPending"   color="#F59E0B" icon={Clock} />
          <StatsCard count={approved}  labelKey="verify.statsApproved"  color="#10B981" icon={CheckCircle2} />
          <StatsCard count={rejected}  labelKey="verify.statsRejected"  color="#EF4444" icon={XCircle} />
          <StatsCard count={suspended} labelKey="verify.statsSuspended" color="#64748B" icon={Slash} />
        </div>

        {/* ── Toolbar ── */}
        <div className="flex gap-3 flex-wrap" style={{ ...glass.card, borderRadius: "1rem", padding: "1rem" }}>
          {/* Search */}
          <div className="relative flex-1 min-w-[180px]">
            <Search className="absolute start-3 top-1/2 -translate-y-1/2 w-4 h-4" style={{ color: "#64748B" }} />
            <input value={search} onChange={e => setSearch(e.target.value)}
              placeholder={t("verify.searchPh")}
              className="w-full ps-9 pe-3.5 py-2.5 rounded-xl text-sm text-white placeholder-[#64748B] outline-none"
              style={{ ...glass.input }} />
          </div>
          {/* Status Filter */}
          <div className="relative">
            <Filter className="absolute start-3 top-1/2 -translate-y-1/2 w-4 h-4 pointer-events-none" style={{ color: "#64748B" }} />
            <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)}
              className="appearance-none ps-9 pe-8 py-2.5 rounded-xl text-sm text-white outline-none cursor-pointer"
              style={{ ...glass.input }}>
              <option value="all" style={{ background: "#0D1A2D" }}>{t("verify.filterAll")}</option>
              <option value="pending" style={{ background: "#0D1A2D" }}>{t("verify.statusPending")}</option>
              <option value="approved" style={{ background: "#0D1A2D" }}>{t("verify.statusApproved")}</option>
              <option value="rejected" style={{ background: "#0D1A2D" }}>{t("verify.statusRejected")}</option>
              <option value="suspended" style={{ background: "#0D1A2D" }}>{t("verify.statusSuspended")}</option>
              <option value="more_docs_needed" style={{ background: "#0D1A2D" }}>{t("verify.statusMoreDocs")}</option>
            </select>
            <ChevronDown className="absolute end-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 pointer-events-none" style={{ color: "#64748B" }} />
          </div>
          {/* Sector Filter */}
          <div className="relative">
            <Layers className="absolute start-3 top-1/2 -translate-y-1/2 w-4 h-4 pointer-events-none" style={{ color: "#64748B" }} />
            <select value={sectorFilter} onChange={e => setSectorFilter(e.target.value)}
              className="appearance-none ps-9 pe-8 py-2.5 rounded-xl text-sm text-white outline-none cursor-pointer"
              style={{ ...glass.input }}>
              <option value="all" style={{ background: "#0D1A2D" }}>{t("verify.allSectors")}</option>
              {Object.keys(SECTOR_META).map(k => (
                <option key={k} value={k} style={{ background: "#0D1A2D" }}>{t(`onboard.sector_${k}`, k)}</option>
              ))}
            </select>
            <ChevronDown className="absolute end-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 pointer-events-none" style={{ color: "#64748B" }} />
          </div>
        </div>

        {/* ── Master Table ── */}
        <div className="rounded-2xl overflow-hidden" style={glass.card}>
          {/* Table Header */}
          <div className="grid gap-3 px-5 py-3 text-[11px] font-bold uppercase tracking-widest"
            style={{ gridTemplateColumns: "2fr 1fr 1fr 1fr 1fr 40px", borderBottom: "1px solid rgba(255,255,255,0.08)", color: "#64748B" }}>
            <span>{t("verify.colName")}</span>
            <span>{t("verify.colSector")}</span>
            <span>{t("verify.colDate")}</span>
            <span>{t("verify.colMobile")}</span>
            <span>{t("verify.colStatus")}</span>
            <span />
          </div>

          {/* Rows */}
          {isLoading ? (
            <div className="flex items-center justify-center py-16">
              <div className="w-8 h-8 border-2 border-blue-400/30 border-t-blue-400 rounded-full animate-spin" />
            </div>
          ) : filtered.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 gap-3">
              <Database className="w-10 h-10" style={{ color: "rgba(255,255,255,0.15)" }} />
              <p className="text-sm" style={{ color: "rgba(255,255,255,0.3)" }}>{t("verify.noRecords")}</p>
              <button onClick={handleSeed} className="text-xs font-semibold px-3 py-1.5 rounded-xl transition-all hover:bg-white/10" style={{ color: "#60A5FA" }}>
                {t("verify.loadDemo")} →
              </button>
            </div>
          ) : (
            <div>
              {filtered.map((reg, i) => {
                const m = SECTOR_META[reg.sectorKey] ?? SECTOR_META.other;
                const Icon = m.icon;
                return (
                  <motion.div key={reg.id}
                    initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.04 }}
                    onClick={() => setSelected(reg)}
                    className="grid gap-3 px-5 py-4 cursor-pointer transition-all group items-center"
                    style={{
                      gridTemplateColumns: "2fr 1fr 1fr 1fr 1fr 40px",
                      borderBottom: i < filtered.length - 1 ? "1px solid rgba(255,255,255,0.05)" : "none",
                    }}
                    onMouseEnter={e => (e.currentTarget.style.background = "rgba(255,255,255,0.04)")}
                    onMouseLeave={e => (e.currentTarget.style.background = "transparent")}>
                    {/* Name */}
                    <div className="flex items-center gap-3 min-w-0">
                      <div className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0"
                        style={{ background: `${m.color}1A`, border: `1px solid ${m.color}33` }}>
                        <Icon className="w-4.5 h-4.5" style={{ color: m.color, width: "1.125rem", height: "1.125rem" }} />
                      </div>
                      <div className="min-w-0">
                        <p className="text-sm font-bold text-white truncate">{reg.businessName}</p>
                        <p className="text-[11px] truncate" style={{ color: "#64748B" }}>{reg.email || reg.city || "—"}</p>
                      </div>
                    </div>
                    {/* Sector */}
                    <SectorChip sectorKey={reg.sectorKey} />
                    {/* Date */}
                    <p className="text-xs" style={{ color: "#64748B" }}>{new Date(reg.submittedAt).toLocaleDateString()}</p>
                    {/* Mobile */}
                    <p className="text-xs font-mono text-white/70">{reg.mobile || "—"}</p>
                    {/* Status */}
                    <StatusBadge status={reg.status} />
                    {/* Action */}
                    <div className="flex items-center justify-center">
                      <ChevronRight className="w-4 h-4 transition-all group-hover:text-blue-400" style={{ color: "#334155" }} />
                    </div>
                  </motion.div>
                );
              })}
            </div>
          )}

          {/* Table Footer */}
          {filtered.length > 0 && (
            <div className="px-5 py-3 flex items-center justify-between"
              style={{ borderTop: "1px solid rgba(255,255,255,0.06)", background: "rgba(0,0,0,0.2)" }}>
              <p className="text-[11px]" style={{ color: "#334155" }}>
                {filtered.length} {t("verify.results")} · {registrations.length} {t("verify.total")}
              </p>
              <p className="text-[11px]" style={{ color: "#334155" }}>LinQi Admin · Verification Queue</p>
            </div>
          )}
        </div>
      </div>

      {/* ── Review Modal ── */}
      <AnimatePresence>
        {selected && (
          <ReviewModal
            reg={selected}
            onClose={() => setSelected(null)}
            onStatusChange={handleStatusChange}
          />
        )}
      </AnimatePresence>
    </div>
  );
}

