import { useState, useCallback, useMemo } from "react";
import { useTranslation } from "react-i18next";
import i18n from "@/i18n";
import { motion, AnimatePresence } from "framer-motion";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import {
  Search, Filter, RefreshCw, CheckCircle2, XCircle, FileText, Clock,
  AlertTriangle, Layers, Truck, Share2, Factory, HeartPulse, ShoppingBag,
  UtensilsCrossed, Building2, ShoppingCart, Pill, Briefcase, X, MapPin,
  Check, Globe, User, Mail, Phone, Database, Star, Award, Shield,
  Package, Users, TrendingUp, DollarSign, Zap, Slash,
  Eye, Navigation2, Play, ChevronRight, Activity,
} from "lucide-react";

/* ══════════════════════════════════════════════════════════════════════
   CONSTANTS
══════════════════════════════════════════════════════════════════════ */
const API = import.meta.env.VITE_API_URL ?? "/api";
const tok = () => localStorage.getItem("pos_auth_token") ?? "";

const LANGS = [{ code: "ku", label: "کوردی" }, { code: "ar", label: "عربی" }, { code: "en", label: "EN" }];

const SM: Record<string, { icon: any; color: string; ku: string }> = {
  distributor:  { icon: Share2,          color: "#F59E0B", ku: "دابەشکار" },
  manufacturer: { icon: Factory,         color: "#EF4444", ku: "کارخانە" },
  hospital:     { icon: HeartPulse,      color: "#EC4899", ku: "نەخۆشخانە / کلینیک" },
  supermarket:  { icon: ShoppingBag,     color: "#8B5CF6", ku: "مارکێت" },
  retail_shop:  { icon: ShoppingCart,    color: "#A855F7", ku: "دوکانی تاکەکەسی" },
  restaurant:   { icon: UtensilsCrossed, color: "#F97316", ku: "چێشتخانە" },
  hotel:        { icon: Building2,       color: "#06B6D4", ku: "هۆتێل" },
  pharmacy:     { icon: Pill,            color: "#22C55E", ku: "دەرمانسازی" },
  delivery:     { icon: Truck,           color: "#10B981", ku: "گەیاندن" },
  office:       { icon: Briefcase,       color: "#3B82F6", ku: "نووسینگە" },
  other:        { icon: Layers,          color: "#6B7280", ku: "بزنسی تر" },
};

const STATUS_CFG: Record<string, { color: string; bg: string; bd: string; icon: any; ku: string }> = {
  pending:          { color: "#FBBF24", bg: "rgba(245,158,11,0.12)", bd: "rgba(245,158,11,0.35)",   icon: Clock,        ku: "چاوەڕوانی پێداچوونەوە" },
  approved:         { color: "#34D399", bg: "rgba(16,185,129,0.12)", bd: "rgba(16,185,129,0.35)",   icon: CheckCircle2, ku: "پەسەندکراو" },
  rejected:         { color: "#F87171", bg: "rgba(239,68,68,0.12)",  bd: "rgba(239,68,68,0.35)",    icon: XCircle,      ku: "ڕەتکراو" },
  suspended:        { color: "#94A3B8", bg: "rgba(100,116,139,0.12)",bd: "rgba(100,116,139,0.35)",  icon: Slash,        ku: "ڕاگیراو" },
  more_docs_needed: { color: "#60A5FA", bg: "rgba(59,130,246,0.12)", bd: "rgba(59,130,246,0.35)",   icon: AlertTriangle,ku: "بەڵگەی زیادە" },
};

const TRUST_BADGES = [
  { key: "verified", ku: "دڵنیاکراو",      en: "Verified",  color: "#10B981", icon: CheckCircle2 },
  { key: "premium",  ku: "پریمیۆم",          en: "Premium",   color: "#3B82F6", icon: Star },
  { key: "gold",     ku: "زێڕین",            en: "Gold",      color: "#F59E0B", icon: Award },
  { key: "trusted",  ku: "متمانەپێکراو",     en: "Trusted",   color: "#8B5CF6", icon: Shield },
];

const GOV_COLORS: Record<string, string> = {
  erbil: "#3B82F6", sulaymaniyah: "#8B5CF6", duhok: "#06B6D4",
  kirkuk: "#F59E0B", halabja: "#EC4899", baghdad: "#EF4444",
};

const DOCS_BY_GROUP: Record<string, { label: string; required: boolean }[]> = {
  enterprise: [
    { label: "تۆمارکردنی بازرگانی",         required: true },
    { label: "مۆڵەتی کارکردن",              required: true },
    { label: "بەڵگەنامەی ناسنامە",         required: true },
    { label: "ISO / بەڵگەنامەی کوالیتی",  required: false },
    { label: "کاتالۆگی بەرهەم (PDF)",      required: false },
  ],
  retail:   [{ label: "بەڵگەنامەی ناسنامە", required: true }],
  delivery: [{ label: "بەڵگەنامەی ناسنامە", required: true }, { label: "تۆمارکردنی بازرگانی", required: true }],
  standard: [{ label: "بەڵگەنامەی ناسنامە", required: true }],
};

const gl = {
  card: {
    background: "rgba(255,255,255,0.04)",
    backdropFilter: "blur(20px)",
    WebkitBackdropFilter: "blur(20px)",
    border: "1px solid rgba(255,255,255,0.08)",
    boxShadow: "0 4px 32px rgba(0,0,0,0.5)",
  } as React.CSSProperties,
  input: {
    background: "rgba(0,0,0,0.3)",
    border: "1px solid rgba(255,255,255,0.10)",
    color: "#FFFFFF",
    borderRadius: "0.75rem",
  } as React.CSSProperties,
};

/* ══════════════════════════════════════════════════════════════════════
   TYPES
══════════════════════════════════════════════════════════════════════ */
interface Registration {
  id: number;
  sectorKey: string;
  sectorGroup: string;
  businessName: string;
  email?: string;
  mobile: string;
  governorate?: string;
  city?: string;
  address?: string;
  extraData?: Record<string, any>;
  status: "pending" | "approved" | "rejected" | "suspended" | "more_docs_needed";
  rejectionReason?: string;
  submittedAt: string;
  reviewedAt?: string;
  reviewedBy?: string;
}

/* ══════════════════════════════════════════════════════════════════════
   API HELPERS
══════════════════════════════════════════════════════════════════════ */
const fetchRegs = (): Promise<Registration[]> =>
  fetch(`${API}/admin/registrations`, { headers: { Authorization: `Bearer ${tok()}` } }).then(r => r.json());

const fetchOverview = () =>
  fetch(`${API}/admin/overview`, { headers: { Authorization: `Bearer ${tok()}` } }).then(r => r.ok ? r.json() : null);

/* ══════════════════════════════════════════════════════════════════════
   UTILS
══════════════════════════════════════════════════════════════════════ */
function parseCoords(address?: string): [number, number] {
  if (!address) return [36.1911, 44.0092];
  const m = address.match(/(-?\d+\.\d+)\s*,\s*(-?\d+\.\d+)/);
  return m ? [parseFloat(m[1]), parseFloat(m[2])] : [36.1911, 44.0092];
}
function fmtIQD(n: number) {
  if (n >= 1e9) return `${(n / 1e9).toFixed(1)}B IQD`;
  if (n >= 1e6) return `${(n / 1e6).toFixed(1)}M IQD`;
  if (n >= 1e3) return `${(n / 1e3).toFixed(0)}K IQD`;
  return `${n.toFixed(0)} IQD`;
}

/* ══════════════════════════════════════════════════════════════════════
   ATOMS
══════════════════════════════════════════════════════════════════════ */
function StatusBadge({ status }: { status: string }) {
  const c = STATUS_CFG[status] ?? STATUS_CFG.pending;
  const I = c.icon;
  return (
    <span className="inline-flex items-center gap-1.5 px-2 py-1 rounded-full text-[10px] font-bold whitespace-nowrap"
      style={{ background: c.bg, border: `1px solid ${c.bd}`, color: c.color }}>
      <I className="w-3 h-3" />{c.ku}
    </span>
  );
}

function SectorChip({ sectorKey }: { sectorKey: string }) {
  const m = SM[sectorKey] ?? SM.other;
  const I = m.icon;
  return (
    <span className="inline-flex items-center gap-1 px-2 py-1 rounded-lg text-[10px] font-semibold"
      style={{ background: `${m.color}1A`, border: `1px solid ${m.color}40`, color: m.color }}>
      <I className="w-3 h-3" />{m.ku}
    </span>
  );
}

function GovChip({ gov }: { gov?: string }) {
  if (!gov) return null;
  const color = GOV_COLORS[gov.toLowerCase()] ?? "#64748B";
  return (
    <span className="inline-flex items-center gap-1 px-2 py-1 rounded-lg text-[10px] font-semibold"
      style={{ background: `${color}15`, border: `1px solid ${color}35`, color }}>
      <MapPin className="w-2.5 h-2.5" />{gov}
    </span>
  );
}

function TrustPill({ badge }: { badge: string }) {
  const b = TRUST_BADGES.find(x => x.key === badge);
  if (!b) return null;
  const I = b.icon;
  return (
    <span className="inline-flex items-center gap-1 px-2 py-1 rounded-full text-[10px] font-black"
      style={{ background: `${b.color}22`, border: `1px solid ${b.color}55`, color: b.color }}>
      <I className="w-3 h-3" />{b.ku}
    </span>
  );
}

function DocDots({ sectorGroup }: { sectorGroup: string }) {
  const docs = DOCS_BY_GROUP[sectorGroup] ?? DOCS_BY_GROUP.standard;
  const uploaded = docs.filter(d => d.required).length;
  const pct = Math.round((uploaded / docs.length) * 100);
  const color = pct === 100 ? "#10B981" : pct >= 60 ? "#F59E0B" : "#EF4444";
  return (
    <div className="flex items-center gap-1">
      {docs.map((d, i) => (
        <div key={i} className="w-2.5 h-2.5 rounded-full transition-all"
          style={{ background: i < uploaded ? color : "rgba(255,255,255,0.10)" }} />
      ))}
      <span className="text-[10px] font-bold ms-1" style={{ color }}>{pct}%</span>
    </div>
  );
}

/* ══════════════════════════════════════════════════════════════════════
   METRIC CARD
══════════════════════════════════════════════════════════════════════ */
function MetricCard({ title, value, sub, icon: I, color, trend, delay = 0 }: {
  title: string; value: string; sub?: string; icon: any; color: string;
  trend?: "up" | "down"; delay?: number;
}) {
  return (
    <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay, duration: 0.4 }}
      className="flex-1 min-w-[200px] rounded-2xl p-5 relative overflow-hidden cursor-default"
      style={{ ...gl.card, boxShadow: `0 0 40px ${color}08, 0 4px 24px rgba(0,0,0,0.5)` }}>
      <div className="absolute -top-10 -end-10 w-32 h-32 rounded-full blur-3xl opacity-[0.15]"
        style={{ background: color }} />
      <div className="flex items-start justify-between mb-4 relative z-10">
        <div className="w-11 h-11 rounded-2xl flex items-center justify-center"
          style={{ background: `${color}20`, border: `1px solid ${color}40` }}>
          <I className="w-5 h-5" style={{ color }} />
        </div>
        {trend && (
          <div className="flex items-center gap-1 text-[10px] font-bold px-2 py-1 rounded-lg"
            style={trend === "up"
              ? { background: "rgba(16,185,129,0.15)", color: "#34D399" }
              : { background: "rgba(239,68,68,0.15)", color: "#F87171" }}>
            {trend === "up" ? <TrendingUp className="w-3 h-3" /> : <AlertTriangle className="w-3 h-3" />}
            {trend === "up" ? "+12.4%" : "-2.1%"}
          </div>
        )}
      </div>
      <p className="text-2xl font-black text-white mb-0.5 relative z-10">{value}</p>
      {sub && <p className="text-[11px] relative z-10 mb-1" style={{ color: "#64748B" }}>{sub}</p>}
      <p className="text-[11px] font-semibold relative z-10" style={{ color: "#475569" }}>{title}</p>
    </motion.div>
  );
}

/* ══════════════════════════════════════════════════════════════════════
   LEAFLET MAP (embedded via srcDoc — zero package deps)
══════════════════════════════════════════════════════════════════════ */
function LeafletMap({ lat, lng, label }: { lat: number; lng: number; label?: string }) {
  const safeLabel = (label ?? "Business Location").replace(/['"<>]/g, " ");
  const html = `<!DOCTYPE html><html><head>
  <meta charset="utf-8"/>
  <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"/>
  <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
  <style>*{margin:0;padding:0}html,body{height:100%;background:#050d1a}#map{height:100%}</style>
  </head><body><div id="map"></div><script>
  const m=L.map('map',{zoomControl:true}).setView([${lat},${lng}],15);
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OSM',maxZoom:19}).addTo(m);
  const icon=L.divIcon({className:'',
    html:'<div style="width:38px;height:38px;background:#3B82F6;border:3px solid white;border-radius:50%;display:flex;align-items:center;justify-content:center;box-shadow:0 0 24px rgba(59,130,246,0.8);font-size:18px">📍</div>',
    iconSize:[38,38],iconAnchor:[19,19]});
  L.marker([${lat},${lng}],{icon}).addTo(m).bindPopup('<b>${safeLabel}</b>').openPopup();
  </script></body></html>`;
  return (
    <iframe srcDoc={html} width="100%" style={{ height: 260, border: 0, borderRadius: "0.875rem", display: "block" }}
      title="GPS" sandbox="allow-scripts" />
  );
}

/* ══════════════════════════════════════════════════════════════════════
   SECTOR FIELDS GRID
══════════════════════════════════════════════════════════════════════ */
const FIELD_LABELS: Record<string, string> = {
  licenseNumber: "ژمارەی مۆڵەت", managerName: "ناوی بەڕێوەبەر",
  brands: "براندەکان", productCategories: "پۆلی بەرهەم",
  productionCapacity: "ئامادەکردنی بەرهەم", deliveryArea: "ناوچەی دابەشکردن",
  whatsapp: "واتساپ", leadTime: "ماوەی گەیاندن",
  companyReg: "تۆمارکردنی کۆمپانیا", nationalId: "ناسنامەی نیشتمانی",
  truckSizes: "جۆری ئۆتۆمبێل", coverageArea: "ناوچەی چوونەسەر",
  numTrucks: "ژمارەی ئۆتۆمبێل", businessName: "ناوی بزنس",
  email: "ئیمەیل", mobile: "مۆبایل", governorate: "پارێزگا",
  city: "شار", address: "ناونیشان",
};
const SKIP_KEYS = new Set(["password", "confirmPassword", "trustBadge"]);

function SectorFields({ extraData }: { extraData?: Record<string, any> }) {
  if (!extraData) return <p className="text-xs text-white/20 py-4 text-center">هیچ زانیارییەکی زیادە نییە</p>;
  const entries = Object.entries(extraData).filter(([k, v]) => !SKIP_KEYS.has(k) && v !== null && v !== undefined && v !== "");
  if (!entries.length) return <p className="text-xs text-white/20 py-4 text-center">هیچ زانیارییەکی زیادە نییە</p>;
  return (
    <div className="grid grid-cols-2 gap-2">
      {entries.map(([k, v]) => (
        <div key={k} className="p-3 rounded-xl"
          style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.06)" }}>
          <p className="text-[9px] font-bold uppercase tracking-widest mb-1" style={{ color: "#3B82F6" }}>
            {FIELD_LABELS[k] ?? k}
          </p>
          <p className="text-xs font-semibold text-white break-all">
            {Array.isArray(v) ? v.join(" · ") : String(v)}
          </p>
        </div>
      ))}
    </div>
  );
}

/* ══════════════════════════════════════════════════════════════════════
   DOCUMENT MATRIX
══════════════════════════════════════════════════════════════════════ */
function DocMatrix({ sectorGroup }: { sectorGroup: string }) {
  const docs = DOCS_BY_GROUP[sectorGroup] ?? DOCS_BY_GROUP.standard;
  return (
    <div className="space-y-2">
      {docs.map(({ label, required }, i) => (
        <div key={i} className="flex items-center gap-3 p-3 rounded-xl"
          style={{ background: "rgba(255,255,255,0.03)", border: `1px solid ${required ? "rgba(16,185,129,0.25)" : "rgba(255,255,255,0.06)"}` }}>
          <div className="w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0"
            style={{ background: required ? "rgba(16,185,129,0.15)" : "rgba(255,255,255,0.05)" }}>
            <FileText className="w-4 h-4" style={{ color: required ? "#34D399" : "#334155" }} />
          </div>
          <div className="flex-1">
            <p className="text-xs font-semibold text-white">{label}</p>
            <p className="text-[10px]" style={{ color: "#475569" }}>{required ? "پێویست" : "ئارەزوومەندانە"}</p>
          </div>
          <span className={`text-[10px] font-bold flex items-center gap-1 ${required ? "text-emerald-400" : "text-slate-600"}`}>
            {required ? <><Check className="w-3 h-3" />بارکراو</> : "— نابارکراو"}
          </span>
        </div>
      ))}
    </div>
  );
}

/* ══════════════════════════════════════════════════════════════════════
   REVIEW MODAL
══════════════════════════════════════════════════════════════════════ */
function ReviewModal({ reg, onClose, onUpdate }: {
  reg: Registration;
  onClose: () => void;
  onUpdate: (id: number, status: string, reason?: string, badge?: string) => Promise<void>;
}) {
  const [tab, setTab] = useState<"creds" | "docs" | "map">("creds");
  const [action, setAction] = useState("");
  const [badge, setBadge] = useState("verified");
  const [reason, setReason] = useState(reg.rejectionReason ?? "");
  const [saving, setSaving] = useState(false);
  const sm = SM[reg.sectorKey] ?? SM.other;
  const SIcon = sm.icon;
  const [lat, lng] = parseCoords(reg.address);
  const trustBadge = reg.extraData?.trustBadge as string | undefined;

  const confirm = async () => {
    if (!action) return;
    setSaving(true);
    try {
      await onUpdate(reg.id, action, action === "rejected" ? reason : undefined, action === "approved" ? badge : undefined);
    } finally {
      setSaving(false);
      setAction("");
    }
  };

  const MODAL_TABS = [
    { key: "creds" as const, label: "بەڵگەنامەی بزنس", icon: User },
    { key: "docs"  as const, label: "بەڵگەنامەکان",    icon: FileText },
    { key: "map"   as const, label: "شوێنی GPS",         icon: MapPin },
  ];
  const ACTIONS = [
    { key: "approved",         icon: CheckCircle2, color: "#10B981", label: "پەسەندکردن و ئیشارەدان" },
    { key: "rejected",         icon: XCircle,      color: "#EF4444", label: "ڕەتکردنەوە لەگەڵ هۆکار" },
    { key: "more_docs_needed", icon: FileText,     color: "#3B82F6", label: "داواکردنی بەڵگەی زیادە" },
    { key: "suspended",        icon: Slash,        color: "#64748B", label: "ڕاگرتنی ئەکاونت" },
  ];

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
      className="fixed inset-0 z-50 flex items-center justify-end"
      style={{ background: "rgba(2,8,20,0.75)", backdropFilter: "blur(10px)", WebkitBackdropFilter: "blur(10px)" }}
      onClick={e => e.target === e.currentTarget && onClose()}>
      <motion.div
