  { buyer: "هۆتێلی پارک سویتس",     sector: "hotel",       qty: "200 unit", product: "شامپوی Dove",    status: "awarded", lead: 1 },
  { buyer: "چێشتخانەی سۆفی",        sector: "restaurant",  qty: "50 L",     product: "ڕوونی زەیتووی", status: "open",    lead: 2 },
  { buyer: "سوپەرمارکێتی نەورۆز",   sector: "supermarket", qty: "300 box",  product: "شکر سپی",        status: "open",    lead: 4 },
];

function BuyersHub({ data }: { data: any }) {
  const customers: any[] = data?.customers ?? [];
  return (
    <div className="space-y-4">
