                <p className="text-[10px]" style={{ color: "#334155" }}>{c.phone ?? c.email ?? "—"}</p>
              </div>
              {c.totalDebt > 0 && (
                <p className="text-xs font-bold" style={{ color: "#F59E0B" }}>{c.totalDebt?.toLocaleString()} IQD</p>
              )}
