/* ══════════════════════════════════════════════════════════════════════
   MAIN — LinQi Central Admin Console
══════════════════════════════════════════════════════════════════════ */
export default function AdminVerification() {
  const queryClient = useQueryClient();
  const [lang, setLang] = useState(i18n.language);
  const [tab, setTab] = useState<"queue" | "suppliers" | "buyers" | "logistics">("queue");
  const [selected, setSelected] = useState<Registration | null>(null);
  const [seeding, setSeeding] = useState(false);

  const { data: regs = [], isLoading: regsLoading, refetch } = useQuery({
    queryKey: ["admin-regs"],
    queryFn: fetchRegs,
    refetchInterval: 15000,
  });

  const { data: overview } = useQuery({
    queryKey: ["admin-overview"],
    queryFn: fetchOverview,
    refetchInterval: 60000,
  });

  const updateMut = useMutation({
    mutationFn: async ({ id, status, reason, badge }: { id: number; status: string; reason?: string; badge?: string }) => {
      const res = await fetch(`${API}/admin/registrations/${id}/status`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${tok()}` },
        body: JSON.stringify({ status, rejectionReason: reason, trustBadge: badge }),
      });
      if (!res.ok) throw new Error("Failed");
      return res.json();
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ["admin-regs"] }),
  });

  const handleUpdate = useCallback(async (id: number, status: string, reason?: string, badge?: string) => {
    const updated = await updateMut.mutateAsync({ id, status, reason, badge });
    setSelected(prev => prev?.id === id ? { ...prev, ...updated } : prev);
  }, [updateMut]);

  const handleSeed = async () => {
    setSeeding(true);
    try {
      await fetch(`${API}/admin/registrations/seed`, { method: "POST", headers: { Authorization: `Bearer ${tok()}` } });
      await refetch();
    } finally { setSeeding(false); }
  };

  const switchLang = (code: string) => {
    i18n.changeLanguage(code); setLang(code);
    document.documentElement.dir = code === "ku" || code === "ar" ? "rtl" : "ltr";
  };

  /* Derived metrics */
  const pending      = regs.filter(r => r.status === "pending").length;
  const approved     = regs.filter(r => r.status === "approved").length;
  const activeSects  = new Set(regs.map(r => r.sectorKey)).size;
  const deliveryRegs = useMemo(() => regs.filter(r => r.sectorKey === "delivery"), [regs]);
  const totalRev     = overview?.totalRevenue ?? 0;
  const commission   = totalRev * 0.015;

  const TABS = [
    { key: "queue"     as const, label: "خشتەی داواکارییەکان", icon: FileText,  badge: pending },
    { key: "suppliers" as const, label: "دابەشکاران",          icon: Package,   badge: 0 },
    { key: "buyers"    as const, label: "کڕیارەکان",            icon: Users,     badge: 0 },
    { key: "logistics" as const, label: "لۆجیستیک",             icon: Truck,     badge: 0 },
  ];

  const rtl = lang === "ku" || lang === "ar";

  return (
    <div className="min-h-screen text-white relative" style={{ background: "#050d1a", direction: rtl ? "rtl" : "ltr" }}>
      {/* Ambient orbs */}
      <div className="fixed inset-0 pointer-events-none overflow-hidden z-0">
        <div className="absolute top-0 start-1/4 w-[700px] h-[350px] rounded-full opacity-[0.04]"
          style={{ background: "radial-gradient(circle, #3B82F6, transparent 65%)" }} />
        <div className="absolute bottom-1/4 end-1/4 w-[500px] h-[500px] rounded-full opacity-[0.025]"
          style={{ background: "radial-gradient(circle, #8B5CF6, transparent 65%)" }} />
      </div>

      {/* ── HEADER ─────────────────────────────────────────────────── */}
      <header className="relative z-20 sticky top-0"
        style={{ background: "rgba(5,13,26,0.92)", backdropFilter: "blur(20px)", WebkitBackdropFilter: "blur(20px)", borderBottom: "1px solid rgba(255,255,255,0.07)" }}>
        <div className="max-w-screen-2xl mx-auto px-5 h-14 flex items-center gap-3">
          {/* Logo */}
          <div className="flex items-center gap-2.5 flex-shrink-0">
            <div className="w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0"
              style={{ background: "linear-gradient(135deg,#3B82F6,#8B5CF6)", boxShadow: "0 0 20px rgba(59,130,246,0.45)" }}>
              <Zap className="w-4 h-4 text-white" />
            </div>
            <div className="hidden sm:block">
              <p className="text-[9px] font-mono text-blue-400/60 uppercase tracking-widest leading-none">LinQi Platform</p>
              <p className="text-xs font-black text-white leading-tight">Central Admin Console</p>
            </div>
          </div>
          <div className="h-4 w-px" style={{ background: "rgba(255,255,255,0.08)" }} />

          {/* Live pill */}
          <div className="hidden sm:flex items-center gap-1.5 px-2.5 py-1 rounded-full flex-shrink-0"
            style={{ background: "rgba(16,185,129,0.12)", border: "1px solid rgba(16,185,129,0.3)" }}>
            <motion.div animate={{ opacity: [1, 0.3, 1] }} transition={{ duration: 1.5, repeat: Infinity }}
              className="w-1.5 h-1.5 rounded-full bg-emerald-400" />
            <span className="text-[10px] font-black text-emerald-400">LIVE</span>
          </div>

          <div className="flex-1" />

          {/* Lang */}
          <div className="flex items-center gap-0.5 p-1 rounded-xl"
            style={{ background: "rgba(255,255,255,0.05)", border: "1px solid rgba(255,255,255,0.08)" }}>
            {LANGS.map(l => (
              <button key={l.code} onClick={() => switchLang(l.code)}
                className="px-2.5 py-1 rounded-lg text-xs font-bold transition-all"
                style={lang === l.code
                  ? { background: "rgba(59,130,246,0.35)", color: "#FFFFFF" }
                  : { color: "#475569" }}>
                {l.label}
              </button>
            ))}
          </div>

          {/* Seed */}
          <button onClick={handleSeed} disabled={seeding}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold transition-colors flex-shrink-0"
            style={{ background: "rgba(16,185,129,0.12)", border: "1px solid rgba(16,185,129,0.3)", color: "#34D399" }}>
            {seeding
              ? <div className="w-3.5 h-3.5 border-2 border-emerald-300/30 border-t-emerald-300 rounded-full animate-spin" />
              : <Database className="w-3.5 h-3.5" />}
            <span className="hidden sm:inline">داتای نموونە</span>
          </button>

          {/* Refresh */}
          <button onClick={() => refetch()}
            className="w-8 h-8 rounded-xl border flex items-center justify-center transition-colors flex-shrink-0"
            style={{ border: "1px solid rgba(255,255,255,0.08)", color: "#334155" }}
            onMouseEnter={e => (e.currentTarget.style.color = "#3B82F6")}
            onMouseLeave={e => (e.currentTarget.style.color = "#334155")}>
            <RefreshCw className="w-4 h-4" />
          </button>

          {/* Dev badge */}
          <div className="hidden sm:flex items-center gap-2 px-2.5 py-1.5 rounded-xl flex-shrink-0"
            style={{ background: "rgba(99,102,241,0.12)", border: "1px solid rgba(99,102,241,0.3)" }}>
            <div className="w-5 h-5 rounded-full bg-gradient-to-br from-indigo-500 to-violet-600 flex items-center justify-center text-white text-[9px] font-black">D</div>
            <span className="text-[11px] font-semibold text-indigo-300">LinQi Dev Admin</span>
          </div>
        </div>
      </header>

      {/* ── MAIN CONTENT ───────────────────────────────────────────── */}
      <main className="relative z-10 max-w-screen-2xl mx-auto px-5 py-6 space-y-6">

        {/* 4 Metric cards */}
        <div className="flex gap-4 flex-wrap">
          <MetricCard
            title="کۆی فرۆشی نیشتمانی — عێراق"
            value={totalRev > 0 ? fmtIQD(totalRev) : "—"}
            sub="ڕێزمانی پلاتفۆرم · داتای ڕاستەوخۆ"
            icon={DollarSign} color="#3B82F6" trend="up" delay={0} />
          <MetricCard
            title="داهاتی پلاتفۆرم (عمولەی ئۆتۆماتیکی)"
            value={commission > 0 ? fmtIQD(commission) : "—"}
            sub="١.٥٪ کۆی فرۆشەکان · ئۆتۆماتیک"
            icon={TrendingUp} color="#10B981" trend="up" delay={0.07} />
          <MetricCard
            title="قەوارەی پیشەسازی ئەکتیڤ"
            value={activeSects > 0 ? `${activeSects} قەوارە` : "١١ قەوارە"}
            sub="دابەشکار · کارخانە · هۆتێل · گەیاندن…"
            icon={Layers} color="#8B5CF6" delay={0.14} />
          <MetricCard
            title="کۆمپانیا دڵنیاکراو / چاوەڕوانی پێداچوونەوە"
            value={`${approved} دڵنیا`}
            sub={`${pending} چاوەڕوانی پێداچوونەوە`}
            icon={CheckCircle2} color="#F59E0B"
            trend={pending > 3 ? "down" : "up"} delay={0.21} />
        </div>

        {/* Tab navigation */}
        <div className="flex items-center gap-1 p-1 rounded-2xl w-fit"
          style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.07)" }}>
          {TABS.map(({ key, label, icon: TI, badge }) => (
            <button key={key} onClick={() => setTab(key)}
              className="relative flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-semibold transition-all"
              style={tab === key
                ? { background: "rgba(59,130,246,0.2)", color: "#FFFFFF", border: "1px solid rgba(99,179,255,0.45)", boxShadow: "0 0 20px rgba(59,130,246,0.12)" }
                : { background: "transparent", color: "#334155", border: "1px solid transparent" }}>
              <TI className="w-4 h-4" style={tab === key ? { color: "#60A5FA" } : undefined} />
              <span className="hidden sm:inline">{label}</span>
              {badge > 0 && (
                <motion.span animate={{ scale: [1, 1.15, 1] }} transition={{ duration: 1.5, repeat: Infinity }}
                  className="absolute -top-1.5 -end-1.5 w-4 h-4 rounded-full flex items-center justify-center text-[9px] font-black"
                  style={{ background: "#EF4444", color: "#FFFFFF" }}>
                  {badge}
                </motion.span>
              )}
            </button>
          ))}
        </div>

        {/* Tab content */}
        <AnimatePresence mode="wait">
          <motion.div key={tab} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -8 }} transition={{ duration: 0.22 }}>
            {tab === "queue"     && <VerifQueue regs={regs} loading={regsLoading} onReview={setSelected} onSeed={handleSeed} />}
            {tab === "suppliers" && <SuppliersLedger data={overview} />}
            {tab === "buyers"    && <BuyersHub data={overview} />}
            {tab === "logistics" && <LogisticsTracker deliveryRegs={deliveryRegs} />}
          </motion.div>
        </AnimatePresence>
      </main>

      {/* Review Modal */}
      <AnimatePresence>
        {selected && (
          <ReviewModal reg={selected} onClose={() => setSelected(null)} onUpdate={handleUpdate} />
        )}
      </AnimatePresence>
    </div>
  );
}

